<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/design.css"><title>My Bookings</title></head><body class="dashboard-page"><header class="dashboard-header"><a href="/">SUN SON SOLAR</a><span><?= esc(session()->get('name')) ?></span><a href="/logout">Logout</a></header><main class="section">
<h1>Service Schedule</h1><?php if(session('message')):?><div class="alert success"><?= esc(session('message')) ?></div><?php endif;?>
<div class="card"><h2>Request a Service</h2><form method="post" action="/customer/bookings"><?= csrf_field() ?><label>Service</label><select name="service_type" required><option>Consultation</option><option>Installation</option><option>Maintenance</option></select><label>Preferred Date</label><input type="date" name="preferred_date" required><label>Service Address</label><input name="address" required><label>Notes</label><textarea name="notes"></textarea><button class="button primary">Submit Request</button></form></div>
<div class="card"><h2>My Requests</h2><?php foreach($bookings as $b):?><p><strong><?= esc($b['service_type']) ?></strong> · <?= esc($b['preferred_date']) ?> · <?= esc($b['status']) ?><?php if($b['status']==='Pending'):?><form class="inline" method="post" action="/customer/bookings/cancel/<?= $b['id'] ?>"><?= csrf_field() ?><button>Cancel</button></form><?php endif;?></p><?php endforeach;?></div>
</main><script src="/js/main.js"></script></body></html>